// `schema types` (D40, S.4) through the compiled executable: the output is
// generated from the database (or from a schema file applied in a rolled-back
// transaction), it is deterministic, --check compares it with the file, the
// command leaves pb_data unchanged, and a name clash or a file that would not
// apply is an error. The output is checked against oxfmt, the repository's
// formatter, so the pre-commit hook does not change a generated file.

import { describe, expect, test } from "bun:test";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

import { typesSchema } from "@test/schema/types-fixture";
import { run, startServer, tempDir } from "@test/support/executable";

const repoRoot = resolve(import.meta.dir, "../..");
const superuser = { email: "admin@types.test", password: "1234567890" };

// a data directory with a superuser; the database is created by the command
async function createSite(): Promise<{ root: string; dataDir: string }> {
  const root = tempDir();
  const dataDir = join(root, "pb_data");
  const created = await run([
    "--dir",
    dataDir,
    "superuser",
    "upsert",
    superuser.email,
    superuser.password,
  ]);
  expect(created.exitCode).toBe(0);
  return { root, dataDir };
}

function writeSchema(root: string, name: string, value: unknown): string {
  const path = join(root, name);
  writeFileSync(path, JSON.stringify(value, null, 2));
  return path;
}

// whether oxfmt accepts the file: its exit code is 0 when the format is right
const formatCheck = async (path: string): Promise<number> => {
  const proc = Bun.spawn(
    [
      join(repoRoot, "node_modules/.bin/oxfmt"),
      "--config",
      join(repoRoot, ".oxfmtrc.json"),
      "--check",
      path,
    ],
    { cwd: repoRoot, stdout: "pipe", stderr: "pipe" },
  );
  return proc.exited;
};

// one declaration of a generated file: from its head to its closing brace
function declarationOf(text: string, head: string): string {
  const start = text.indexOf(head);
  expect(start).toBeGreaterThanOrEqual(0);
  return text.slice(start, text.indexOf("\n}", start) + 2);
}

// the SHA-256 of the database files: they must not change under the command
function digests(dataDir: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const name of ["data.db", "auxiliary.db"]) {
    const path = join(dataDir, name);
    if (existsSync(path)) {
      result[name] = createHash("sha256").update(readFileSync(path)).digest("hex");
    }
  }
  return result;
}

describe("schema types", () => {
  test("help lists the command and its flags", async () => {
    const result = await run(["schema", "--help"]);
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("types");

    const types = await run(["schema", "types", "--help"]);
    expect(types.exitCode).toBe(0);
    expect(types.stdout).toContain("--schema");
    expect(types.stdout).toContain("--check");
    expect(types.stdout).toContain("--out");
  });

  test("generates the types of a schema file, deterministically, in the repository's format", async () => {
    const site = await createSite();
    const schema = writeSchema(site.root, "iglo.schema.json", typesSchema);
    const first = join(site.root, "first.ts");
    const second = join(site.root, "second.ts");

    const one = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      first,
    ]);
    expect(one.exitCode).toBe(0);
    const two = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      second,
    ]);
    expect(two.exitCode).toBe(0);

    const text = readFileSync(first, "utf8");
    expect(text).toBe(readFileSync(second, "utf8"));
    expect(text.startsWith("// Generated by `iglo-base schema types`")).toBe(true);

    // the collections, with the types the spec asks for
    expect(text).toContain("export interface PostsRecord {");
    expect(text).toContain("export interface PostsResponse<Expand = {}> {");
    expect(text).toContain("export type PostsCreate = {");
    expect(text).toContain("export type PostsUpdate = {");
    expect(text).toContain('status: "draft" | "published" | "archived";');
    expect(text).toContain('section?: "" | "news" | "sport";');
    expect(text).toContain('tags?: ("a" | "b")[];');
    expect(text).toContain("meta: { readonly k: string } | null;");
    expect(text).toContain("free?: unknown | null;");
    expect(text).toContain("place: { lon: number; lat: number };");
    expect(text).toContain('cover?: File | Blob | "" | null;');
    expect(text).toContain('"views+"?: number;');
    expect(text).toContain('"gallery-"?: string | string[];');
    expect(text).toContain("/** Images. */");
    expect(text).toContain("/** People who write posts. */");
    expect(text).toContain("export enum Collections {");
    expect(text).toContain(
      'export type TypedPocketBase<C = PocketBase> = Omit<C, "collection"> & {',
    );
    // the client types come from the published package
    expect(text).toContain('import type PocketBase from "@iglo.tech/iglo.base";');
    expect(text).toContain('import type { RecordService } from "@iglo.tech/iglo.base";');
    expect(text).not.toContain('"iglo.base"');
    // a system collection keeps its underscore in its type name
    expect(text).toContain("export interface _OtpsRecord {");
    expect(text).toContain('_Otps = "_otps",');
    // hidden fields are not in the response, and a view has its own fields
    expect(declarationOf(text, "export interface PostsResponse<")).not.toContain("pin");
    expect(declarationOf(text, "export interface PostsRecord {")).toContain("pin: string;");
    expect(declarationOf(text, "export interface PostListResponse<")).toContain("title: string;");
    // a password of an auth collection is set on create, and the email is optional on a response
    expect(text).toContain("passwordConfirm: string;");
    expect(text).toContain("email?: string;");
    // tokenKey is the server's, and autodate fields are not set by a request
    expect(text).not.toContain("tokenKey?:");
    expect(declarationOf(text, "export type PostsCreate = {")).not.toContain("created");
    expect(declarationOf(text, "export type PostsCreate = {")).toContain("pin?: string;");
    // a file is uploaded on create; an update also keeps a file by its name and clears it with "" or null
    expect(declarationOf(text, "export type PostsUpdate = {")).toContain(
      "cover?: File | Blob | string | null;",
    );
    expect(declarationOf(text, "export type PostsUpdate = {")).toContain(
      '"+cover"?: File | Blob | string;',
    );
    expect(declarationOf(text, "export type PostsUpdate = {")).toContain(
      "gallery?: File | Blob | string | (File | Blob | string)[] | null;",
    );
    expect(declarationOf(text, "export type PostsCreate = {")).toContain(
      'gallery?: File | Blob | (File | Blob)[] | "" | null;',
    );
  });

  test("--check passes on fresh output and fails, naming the file, after a schema change", async () => {
    const site = await createSite();
    const schema = writeSchema(site.root, "iglo.schema.json", typesSchema);
    const out = join(site.root, "iglo.types.ts");

    const generated = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      out,
    ]);
    expect(generated.exitCode).toBe(0);

    const fresh = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      out,
      "--check",
    ]);
    expect(fresh.exitCode).toBe(0);

    const changed = structuredClone(typesSchema);
    const fields: Record<string, unknown> = {
      ...changed.collections.posts.fields,
      subtitle: { type: "text" },
    };
    changed.collections.posts.fields = fields as typeof changed.collections.posts.fields;
    const changedSchema = writeSchema(site.root, "changed.json", changed);
    const stale = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      changedSchema,
      "--out",
      out,
      "--check",
    ]);
    expect(stale.exitCode).not.toBe(0);
    expect(stale.stderr).toContain(JSON.stringify(out));
    expect(stale.stderr).toContain("out of date");
    // --check writes nothing
    expect(readFileSync(out, "utf8")).not.toContain("subtitle");
  });

  test("--schema leaves pb_data unchanged and makes no backup", async () => {
    const site = await createSite();
    const before = digests(site.dataDir);
    const schema = writeSchema(site.root, "iglo.schema.json", typesSchema);

    const result = await run(["--dir", site.dataDir, "schema", "types", "--schema", schema]);
    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("export interface PostsRecord {");
    expect(digests(site.dataDir)).toEqual(before);
    expect(existsSync(join(site.dataDir, "backups"))).toBe(false);
  });

  test("without --schema, the types come from the database: the file's descriptions and tsType are not in it", async () => {
    const site = await createSite();
    const schema = writeSchema(site.root, "iglo.schema.json", typesSchema);
    const applied = await run(["--dir", site.dataDir, "schema", "types", "--schema", schema]);
    expect(applied.exitCode).toBe(0);

    // a rolled-back apply keeps nothing: the schema is applied by a start
    const server = await startServer(["--schema", schema], site.dataDir);
    const stopped = await server.stop();
    expect(stopped.exitCode).toBe(0);

    const text = await run(["--dir", site.dataDir, "schema", "types"]);
    expect(text.exitCode).toBe(0);
    expect(text.stdout).toContain("export interface PostsRecord {");
    expect(text.stdout).not.toContain("/** Images. */");
    expect(text.stdout).not.toContain("{ readonly k: string }");
    expect(text.stdout).toContain("meta: unknown | null;");
  });

  test("two collections with one type name are an error that names both", async () => {
    const site = await createSite();
    const clash = {
      collections: {
        my_posts: { type: "base", fields: { title: { type: "text" } } },
        myPosts: { type: "base", fields: { title: { type: "text" } } },
      },
    };
    const schema = writeSchema(site.root, "clash.json", clash);
    const out = join(site.root, "clash.ts");
    const result = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      out,
    ]);
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr).toContain("MyPosts");
    expect(result.stderr).toContain("my_posts");
    expect(result.stderr).toContain("myPosts");
    expect(existsSync(out)).toBe(false);
  });

  test("a schema that would not apply writes no types", async () => {
    const site = await createSite();
    const broken = structuredClone(typesSchema);
    // more selected values than the field has values: the apply refuses it
    broken.collections.posts.fields.tags = { type: "select", values: ["a"], maxSelect: 3 } as never;
    const schema = writeSchema(site.root, "broken.json", broken);
    const out = join(site.root, "broken.ts");
    const result = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      out,
    ]);
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr).toContain("would not apply");
    expect(existsSync(out)).toBe(false);
  });

  test("--check needs --out", async () => {
    const site = await createSite();
    const result = await run(["--dir", site.dataDir, "schema", "types", "--check"]);
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr).toContain("--out");
  });

  test("the generated file is already in oxfmt's format", async () => {
    const site = await createSite();
    const schema = writeSchema(site.root, "iglo.schema.json", typesSchema);
    const out = join(site.root, "formatted.ts");
    const generated = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      out,
    ]);
    expect(generated.exitCode).toBe(0);

    // the control: a file oxfmt would change fails the same check
    const unformatted = join(site.root, "unformatted.ts");
    writeFileSync(unformatted, "const   x = 'a'\n");
    expect(await formatCheck(unformatted)).not.toBe(0);
    expect(await formatCheck(out)).toBe(0);
  });

  test("a long name, long values, quotes and long types stay in oxfmt's format", async () => {
    const site = await createSite();
    // the collection's name is as long as a name can be (255 characters), and its
    // fields are long; the values of the selects are long or contain quotes
    const longName = `category_${"with_a_long_name_".repeat(12)}`.slice(0, 255);
    const longField = "a_very_long_field_name_".repeat(4).replace(/_$/, "");
    const longValues = [1, 2, 3, 4, 5, 6].map((i) => `alpha_value_number_${i}_with_a_long_name`);
    const stress = {
      collections: {
        [longName]: {
          type: "base",
          rules: { list: "", view: "" },
          description:
            "A description that is wider than one hundred columns, so that it is one long line of JSDoc.\nA second line, with a */ inside it.",
          fields: {
            kind: { type: "select", values: longValues, maxSelect: 1, required: true },
            kinds: { type: "select", values: longValues, maxSelect: 6 },
            quoted: { type: "select", values: ['say "hi"', "it's", "both \" and '"], maxSelect: 1 },
            [longField]: { type: "text", description: "A field with a long name." },
            meta: {
              type: "json",
              tsType:
                "{ title: string; subtitle: string; tags: string[]; author: { name: string; email: string } }",
            },
            fn: { type: "json", tsType: "() => void" },
            cond: { type: "json", tsType: "string extends number ? 1 : 2" },
            pair: { type: "json", required: true, tsType: "[number, number]" },
            cover: { type: "file", maxSelect: 1 },
            gallery: { type: "file", maxSelect: 9 },
            badge: { type: "file", maxSelect: 1, required: true },
            ref: { type: "relation", collection: "other", maxSelect: 9 },
          },
        },
        other: { type: "base", rules: { list: "", view: "" }, fields: { title: { type: "text" } } },
      },
    };
    const schema = writeSchema(site.root, "stress.json", stress);
    const out = join(site.root, "stress.ts");
    const generated = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      out,
    ]);
    expect(generated.exitCode).toBe(0);

    const text = readFileSync(out, "utf8");
    expect(text).toContain(`'say "hi"'`);
    // a function type binds looser than a union, so it is parenthesized before null
    expect(text).toContain("fn: (() => void) | null;");
    // a required file is uploaded on create; an optional one also takes "" and null, which upstream ignores
    expect(text).toContain("badge: File | Blob;");
    // the json line is kept by Prettier's ignore comment, the one oxfmt also honours
    expect(text).toContain("// prettier-ignore");
    expect(text).not.toContain("oxfmt-ignore");
    expect(await formatCheck(out)).toBe(0);
  });

  test("a user collection named superusers gets its own types, beside the system collection's", async () => {
    const site = await createSite();
    const schema = writeSchema(site.root, "names.json", {
      collections: {
        superusers: {
          type: "base",
          rules: { list: "", view: "" },
          fields: { title: { type: "text" } },
        },
      },
    });
    const out = join(site.root, "names.ts");
    const result = await run([
      "--dir",
      site.dataDir,
      "schema",
      "types",
      "--schema",
      schema,
      "--out",
      out,
    ]);
    expect(result.exitCode).toBe(0);
    const text = readFileSync(out, "utf8");
    expect(text).toContain("export interface SuperusersRecord {");
    expect(text).toContain("export interface _SuperusersRecord {");
    expect(text).toContain('Superusers = "superusers",');
    expect(text).toContain('_Superusers = "_superusers",');
    expect(text).toContain('"superusers" | Collections.Superusers');
    expect(await formatCheck(out)).toBe(0);
  });
});
